// LastAccessServiceName returns AWS's report display name for a service namespace.
func LastAccessServiceName(namespace string) (string, bool) {
	service, ok := lastAccessServices[namespace]
	return service.name, ok
}

// OrganizationsAccessDefaultRegion returns the region reported before any service activity.
// Absence is preserved; global endpoints alone do not imply a report region.
func OrganizationsAccessDefaultRegion(namespace string) (string, bool) {
	service := lastAccessServices[namespace]
	return service.defaultRegion, service.hasDefaultRegion
}

// OrganizationsAccessTimeSortRank returns the observed ascending order for equal or absent activity times.
// Unknown service namespaces return -1.
func OrganizationsAccessTimeSortRank(namespace string) int {
	service, ok := lastAccessServices[namespace]
	if !ok {
		return -1
	}
	return service.timeSortRank
}

